+	}
+	case "play:build": {
+		run("bunx", ["vite", "build", "--config", "vite.config.ts", ...args], resolve(spatialRoot, "play"));
+		break;
+	}
+	case "play:test": {
+		runVitest("play", ["play/index.ts", "play/host.tsx"]);
+		break;
+	}
+	default: {
+		console.error("usage: bun ./script.ts <js|react|play> <test|dev|build> [...args]");
